// 길이 k인 구간마다 최솟값을 구한다 (d에는 첨자, 값이 앞에서 뒤로 커진다)
deque<int> d;
for (int i = 0; i < n; i++) {
    while (!d.empty() && a[d.back()] >= a[i]) d.pop_back();
    d.push_back(i);
    if (d.front() <= i - k) d.pop_front();     // 구간을 벗어난 첨자
    if (i >= k - 1) print(a[d.front()]);       // 구간 [i-k+1, i]의 최솟값
}

